sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float hue;
uniform float amount;
uniform float saturation;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
float3 hue2rgb(float h) {
    return clamp(abs(mod(h * 6.0 + float3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);
}
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    float3 rgb = float3(src.rgb) / float(src.a);
    float l = luma(rgb);
    float3 tint = hue2rgb(hue / 360.0);
    float3 colored = l < 0.5 ? tint * l * 2.0 : mix(tint, float3(1.0), l * 2.0 - 1.0);
    colored = mix(float3(l), colored, clamp(saturation, 0.0, 1.0));
    return half4(half3(mix(rgb, colored, clamp(amount, 0.0, 1.0))) * src.a, src.a);
}
